165	ACL9SiteMap* ACL9SiteMap::Find(UWorld* World)
166	{
167		if (World == nullptr)
168		{
169			return nullptr;
170		}
171		for (TActorIterator<ACL9SiteMap> It(World); It; ++It)
172		{
173			return *It;
174		}
175		return nullptr;
176	}
