232	FVector ACL9SiteMap::PointToWorld(const FCL9LevelPoint& Point) const
233	{
234		// 지점의 Z는 그 지점이 있는 층의 바닥이다 — 스폰이 2층 방을 고르면 2층에 놓인다.
235		return SiteToWorld(Point.Local) + FVector(0.f, 0.f, Point.Floor * Params.FloorHeight);
