244	void ACL9SiteMap::ClearBuilt()
245	{
246		for (UInstancedStaticMeshComponent* Component : KindComponents)
247		{
248			if (Component != nullptr)
249			{
250				Component->DestroyComponent();
251			}
252		}
253		KindComponents.Reset();
254	
255		for (UPointLightComponent* Lamp : LampComponents)
256		{
257			if (Lamp != nullptr)
258			{
259				Lamp->DestroyComponent();
260			}
261		}
262		LampComponents.Reset();
263		FlickerLamps.Reset();
264		bLampsOn = true;
265	
266		for (AActor* Actor : SpawnedActors)
267		{
268			if (IsValid(Actor))
269			{
270				Actor->Destroy();
271			}
272		}
273		SpawnedActors.Reset();
274	}
