276	void ACL9SiteMap::Tick(float DeltaSeconds)
277	{
278		Super::Tick(DeltaSeconds);
279	
280		// 정전 판정은 게임 스테이트의 것이다. 에디터 월드(게임 스테이트 없음)에서는 늘 켜 둔다.
281		const ACL9GameState* State = GetWorld() != nullptr ? GetWorld()->GetGameState<ACL9GameState>() : nullptr;
282		SetLampsOn(State == nullptr || !State->IsBlackout());
283		TickFlicker();
