305	void ACL9SiteMap::SetLampsOn(bool bOn)
306	{
307		if (bOn == bLampsOn)
308		{
309			return;
310		}
311		bLampsOn = bOn;
312		for (UPointLightComponent* Lamp : LampComponents)
313		{
314			if (Lamp != nullptr)
315			{
316				Lamp->SetVisibility(bOn);
317			}
318		}
319	}
