321	void ACL9SiteMap::MeasurePieces(const UCL9SiteDef& Site, const UCL9DefRegistry& Registry)
322	{
323		// 벽 두께는 표에 적지 않는다 — 벽으로 세울 조각의 얇은 축이 곧 프레임의 벽 두께다.
324		if (const UStaticMesh* WallMesh = LeadMesh(Registry, CL9SegKind::Barn(), Site.Theme))
325		{
326			const FVector MeshSize = WallMesh->GetBoundingBox().GetSize();
327			Params.WallThickness = FMath::Max(FMath::Min(MeshSize.X, MeshSize.Y), 1.f);
328		}
329		// 문 폭도 마찬가지다 — 팩을 갈아 끼우면 개구부가 그 팩 문짝을 따라간다.
330		if (const UStaticMesh* DoorMesh = LeadMesh(Registry, CL9SegKind::Door(), Site.Theme))
331		{
332			const FVector MeshSize = DoorMesh->GetBoundingBox().GetSize();
333			Params.DoorWidth = FMath::Clamp(FMath::Max(MeshSize.X, MeshSize.Y), 1.f, Params.CellSize);
334		}
335	}
