337	void ACL9SiteMap::Build(const UCL9SiteDef& Site, const UCL9DefRegistry& Registry, uint32 Seed, int32 Day)
338	{
339		ClearBuilt();
340	
341		Params = FCL9SiteParams();
342		Params.Theme = Site.Theme;
343		Params.CellSize = FMath::Max(Site.CellSize, 1.f);
344		Params.EntryOffset = Site.EntryOffset;
345	
346		// 한 판의 크기 = 사이트 기준값 × 일자 커브 (module.md 결정 5).
347		// 커브가 비어 있으면 1.0이므로 기준값이 그대로 나온다.
348		const UCL9ProgressionDef* Progression = Registry.GetProgression();
349		const float SizeMult = Progression != nullptr ? Progression->SiteSizeAt(Day) : 1.f;
350		Params.ModuleCount = FMath::Max(2, FMath::RoundToInt(Site.BaseModuleCount * SizeMult));
351	
352		// 층은 일자와 무관하다 — 목적지가 몇 층짜리 건물인가는 그 목적지의 성질이다.
353		Params.MaxFloors = FMath::Clamp(Site.MaxFloors, 1, 8);
354		Params.StairCountMin = FMath::Max(1, Site.StairCountMin);
355		Params.StairCountMax = FMath::Max(Params.StairCountMin, Site.StairCountMax);
356		Params.UpperFloorShare = FMath::Clamp(Site.UpperFloorShare, 0.f, 1.f);
357		Params.bBuildCeilings = Site.bBuildCeilings;
358		Params.LampDensity = FMath::Clamp(Site.LampDensity, 0.f, 1.f);
359		Params.LoopChance = FMath::Clamp(Site.LoopChance, 0.f, 1.f);
360		Params.MainPathShare = FMath::Clamp(Site.MainPathShare, 0.f, 1.f);
361		Params.PassageShare = FMath::Clamp(Site.PassageShare, 0.f, 1.f);
362		Params.DeadEndShare = FMath::Clamp(Site.DeadEndShare, 0.f, 1.f - Params.PassageShare);
363		Params.SpecialCopies = FMath::Max(1, Site.SpecialCopies);
364	
365		MeasurePieces(Site, Registry);
366	
367		TArray<const UCL9ModuleDef*> ModuleDefs;
368		Registry.GatherModules(Site.Theme, ModuleDefs);
369		if (ModuleDefs.Num() == 0 && Seed != 0)
370		{
371			UE_LOG(LogCL9, Error, TEXT("Site map: stage '%s' has no module rows — nothing to assemble (ModuleTable)."), *Site.Theme.ToString());
372		}
373	
374		// 한 층의 높이 = 가장 높은 방의 천장 + 천장 판 + 바닥 판. 판 두께는 조각 표에서
375		// 실측으로 오므로, 팩을 갈아 끼우면 층 높이가 그 팩을 따라간다 (asset-swap.md).
376		{
377			float Tallest = 0.f;
378			for (const UCL9ModuleDef* Def : ModuleDefs)
379			{
380				Tallest = FMath::Max(Tallest, Def->Height);
381			}
382			const UCL9SegKindDef* CeilingKind = Registry.FindSegKind(CL9SegKind::Ceiling());
383			const UCL9SegKindDef* FloorKind = Registry.FindSegKind(CL9SegKind::Floor());
384			const float Sandwich = (CeilingKind != nullptr ? CeilingKind->Height : 30.f)
385				+ (FloorKind != nullptr ? FloorKind->Height : 30.f);
386			Params.FloorHeight = FMath::Max(Tallest, 200.f) + Sandwich;
387		}
388	
389		Layout = CL9SiteLayout::Generate(Params, ModuleDefs, Seed);
390	
391		TArray<FCL9SiteSeg> Segs;
392		CL9SiteLayout::BuildSegments(Params, Layout, Segs);
393	
394		TMap<TPair<FName, UStaticMesh*>, UInstancedStaticMeshComponent*> Components;
395		TMap<FName, FTileReport> Reports;
396		TSet<FName> MissingKinds;
397		TSet<FName> MissingRoles;
398		int32 Placed = 0;
399	
400		// 컴포넌트는 (종류, 메시)마다 하나다 — 같은 메시라도 종류가 다르면 시야 차단
401		// 설정이 달라서 한 인스턴스 묶음에 넣을 수 없다.
402		auto ComponentFor = [this, &Components](const UCL9SegKindDef& Kind, FName KindName, UStaticMesh* Mesh)
403		{
404			const TPair<FName, UStaticMesh*> Key(KindName, Mesh);
405			if (UInstancedStaticMeshComponent* Found = Components.FindRef(Key))
406			{
407				return Found;
408			}
409			UInstancedStaticMeshComponent* Component = NewObject<UInstancedStaticMeshComponent>(
410				this, FName(*FString::Printf(TEXT("Seg_%s_%d"), *KindName.ToString(), KindComponents.Num())));
411			Component->SetMobility(EComponentMobility::Static);
412			Component->SetStaticMesh(Mesh);
413			Component->SetCollisionProfileName(UCollisionProfile::BlockAll_ProfileName);
414			if (!Kind.bBlocksSight)
415			{
416				Component->SetCollisionResponseToChannel(ECC_Visibility, ECR_Ignore);
417				// 소리 파동·카메라가 쓰는 전용 채널 CL9_Occlusion(Config/DefaultEngine.ini, GameTraceChannel2)도
418				// 같은 컬럼 하나로 정한다 — 물통·상자 뒤로 파동이 지나간다 (segkind.md, 2026-09-17)
419				Component->SetCollisionResponseToChannel(ECC_GameTraceChannel2, ECR_Ignore);
420			}
421			Component->SetCanEverAffectNavigation(true);
422			Component->SetupAttachment(GetRootComponent());
423			Components.Add(Key, Component);
424			KindComponents.Add(Component);
425			return Component;
426		};
427	
428		for (const FCL9SiteSeg& Seg : Segs)
429		{
430			const UCL9SegKindDef* Kind = Registry.FindSegKind(Seg.Kind);
431			if (Kind == nullptr)
432			{
433				// `door`는 일부러 행이 없다 — 문짝 메시로 개구부를 채우면 콜리전이 생겨 문이 막힌다.
434				// 그래서 문 자리는 문틀 없는 개구부이고, 없다고 에러를 내지 않는다 (asset-swap.md).
435				if (Seg.Kind != CL9SegKind::Door())
436				{
437					MissingKinds.Add(Seg.Kind);
438				}
439				continue;

440			}
441			const UCL9PieceDef* Piece = Registry.FindPiece(Kind->Piece, Site.Theme);
442			if (Piece == nullptr || Piece->Variants.Num() == 0)
443			{
444				MissingRoles.Add(Kind->Piece);
445				continue;
446			}
447	
448			const FVector2D Size = Seg.Rect.GetSize();
449			const FVector2D Center = Seg.Rect.GetCenter();
450	
451			// 바닥 종류(바닥·마당·디딤판)만 기준점 아래로 자라고, 벽과 천장은 기준점 위로 자란다.
452			const bool bDownward = CL9SegKind::GrowsDown(Seg.Kind);
453			const float Base = bDownward ? Seg.BaseZ - Kind->Height : Seg.BaseZ;
454			const float Top = bDownward ? Seg.BaseZ : Seg.BaseZ + Kind->Height;
455			const FVector Spot(Center.X, Center.Y, (Base + Top) * 0.5f);
456	
457			if (Seg.Kind == CL9SegKind::FlapIn())
458			{
459				UStaticMesh* Mesh = PickMesh(*Piece, Spot);
460				const FVector Extent(Size.X * 0.5f, Size.Y * 0.5f, (Top - Base) * 0.5f);
461				FActorSpawnParameters SpawnParams;
462				SpawnParams.Owner = this;
463				SpawnParams.ObjectFlags |= RF_Transient;
464				SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
465				if (ACL9FlapIn* Flap = GetWorld()->SpawnActor<ACL9FlapIn>(GetActorLocation() + Spot, FRotator::ZeroRotator, SpawnParams))
466				{
467					// 안쪽은 바깥 방향의 반대다 — 배치기가 어느 변에 달았는지 알려 준다
468					Flap->Setup(Extent, FVector(-Seg.Outward.X, -Seg.Outward.Y, 0.f), Mesh);
469					Flap->bIsEditorOnlyActor = bIsEditorOnlyActor;
470					SpawnedActors.Add(Flap);
471					++Placed;
472				}
473				continue;
474			}
475	
476			if (Kind->Placement == ECL9SegPlacement::Tile)
477			{
478				UStaticMesh* Lead = Piece->Variants[0].LoadSynchronous();
479				if (Lead == nullptr)
480				{
481					MissingRoles.Add(Kind->Piece);
482					continue;
483				}
484	
485				// 칸 격자는 첫 변형의 크기로 잡고, 각 칸에는 그 자리에 뽑힌 변형을 그 칸에
486				// 맞춰 앉힌다 — 변형끼리 크기가 어긋나도 칸 밖으로 삐져나오지 않는다.
487				const FVector PieceSize = Lead->GetBoundingBox().GetSize();
488				bool bRunAlongX = true;
489				TArray<FBox> Cells;
490				MakeTileCells(Seg.Rect, Base, Top, PieceSize, bRunAlongX, Cells);
491	
492				FTileReport& Report = Reports.FindOrAdd(Seg.Kind);
493				Report.PieceSize = PieceSize;
494	
495				for (const FBox& Cell : Cells)
496				{
497					UStaticMesh* Mesh = PickMesh(*Piece, Cell.GetCenter());
498					if (Mesh == nullptr)
499					{
500						continue;
501					}
502					FTransform Instance;
503					Report.Note(FitPieceToCell(Cell, Mesh->GetBoundingBox(), bRunAlongX, Instance));
504					ComponentFor(*Kind, Seg.Kind, Mesh)->AddInstance(Instance, /*bWorldSpace*/ false);
505					++Report.Tiles;
506					++Placed;
507				}
508				continue;
509			}
510	
511			if (Kind->Placement == ECL9SegPlacement::Grid)
512			{
513				UStaticMesh* Lead = Piece->Variants[0].LoadSynchronous();
514				if (Lead == nullptr)
515				{
516					MissingRoles.Add(Kind->Piece);
517					continue;
518				}
519	
520				// 두 평면 축 모두 `round(발자국 / 조각)`장 — 모듈 사각형은 칸의 정수배라 1.0으로 떨어지고,
521				// 계단실 띠 같은 짧은 발자국만 한 장이 눌린다. 높이는 발자국 높이(판 두께)에 맞춘다.
522				const FVector PieceSize = Lead->GetBoundingBox().GetSize();
523				const int32 CountX = FMath::Max(1, FMath::RoundToInt(Size.X / FMath::Max(PieceSize.X, 1.f)));
524				const int32 CountY = FMath::Max(1, FMath::RoundToInt(Size.Y / FMath::Max(PieceSize.Y, 1.f)));
525				const FVector2D GridCell(Size.X / CountX, Size.Y / CountY);
526	
527				FTileReport& Report = Reports.FindOrAdd(Seg.Kind);
528				Report.PieceSize = PieceSize;
529				Report.bWarnOnFit = false;
530	
531				for (int32 IY = 0; IY < CountY; ++IY)
532				{
533					for (int32 IX = 0; IX < CountX; ++IX)
534					{
535						const FVector GridSpot(Seg.Rect.Min.X + (IX + 0.5f) * GridCell.X, Seg.Rect.Min.Y + (IY + 0.5f) * GridCell.Y, (Base + Top) * 0.5f);
536						UStaticMesh* Mesh = PickMesh(*Piece, GridSpot);
537						if (Mesh == nullptr)
538						{
539							continue;
540						}
541						const FBox Bounds = Mesh->GetBoundingBox();
542						const FVector MeshSize = Bounds.GetSize().ComponentMax(FVector(1.f));
543						const FVector Scale(GridCell.X / MeshSize.X, GridCell.Y / MeshSize.Y, (Top - Base) / MeshSize.Z);
544						FTransform Instance;
545						Instance.SetScale3D(Scale);
546						Instance.SetLocation(GridSpot - Scale * Bounds.GetCenter());
547						Report.Note(Scale.X);
548						Report.Note(Scale.Y);
549						ComponentFor(*Kind, Seg.Kind, Mesh)->AddInstance(Instance, /*bWorldSpace*/ false);
550						++Report.Tiles;
551						++Placed;
552					}
553				}
554				continue;
555			}
556	
557			UStaticMesh* Mesh = PickMesh(*Piece, Spot);
558			if (Mesh == nullptr)
559			{
560				MissingRoles.Add(Kind->Piece);
561				continue;
562			}
563	
564			FTransform Instance;
565			Instance.SetLocation(FVector(Center.X, Center.Y, (Base + Top) * 0.5f));
566			Instance.SetScale3D(FVector(Size.X, Size.Y, Top - Base) / UnitCube);
567			ComponentFor(*Kind, Seg.Kind, Mesh)->AddInstance(Instance, /*bWorldSpace*/ false);
568			++Placed;
569		}
570	
571		const int32 PropsPlaced = PlaceProps(Segs, Components.Num());
572	
573		for (UInstancedStaticMeshComponent* Component : KindComponents)
574		{
575			Component->RegisterComponent();
576			AddInstanceComponent(Component);
577		}
578		for (UPointLightComponent* Lamp : LampComponents)
579		{
580			Lamp->RegisterComponent();
581			AddInstanceComponent(Lamp);
582		}
583	
584		for (const FName& Kind : MissingKinds)
585		{
586			UE_LOG(LogCL9, Error, TEXT("Site map: seg kind '%s' has no usable row — its boxes were skipped (SegKindTable)."), *Kind.ToString());
587		}
588		for (const FName& MissingRole : MissingRoles)
589		{
590			UE_LOG(LogCL9, Error, TEXT("Site map: theme '%s' has no usable piece for role '%s' — its boxes were skipped (PieceTable)."),
591				*Site.Theme.ToString(), *MissingRole.ToString());
592		}
593		for (const TPair<FName, FTileReport>& Entry : Reports)
594		{
595			const FTileReport& Report = Entry.Value;
596			UE_LOG(LogCL9, Log, TEXT("Site map: '%s' tiled with a %.0f x %.0f x %.0f piece — %d instances, worst run fit %.2f."),
597				*Entry.Key.ToString(), Report.PieceSize.X, Report.PieceSize.Y, Report.PieceSize.Z, Report.Tiles, Report.WorstRunFit);
598			if (Report.bWarnOnFit && (Report.WorstRunFit < TileFitMin || Report.WorstRunFit > TileFitMax))
599			{
600				UE_LOG(LogCL9, Warning, TEXT("Site map: '%s' pieces are stretched %+.0f%% along their run — retune CellSize to this pack's module (docs/systems/asset-swap.md)."),
601					*Entry.Key.ToString(), (Report.WorstRunFit - 1.f) * 100.f);
602			}
603		}
604	
605		if (!Layout.bBuilt)
606		{
607			UE_LOG(LogCL9, Log, TEXT("Site map: nothing built — site '%s', seed %u (0 means the flat level stays as it is)."), *Site.Alias.ToString(), Seed);
608			return;
609		}
610	
611		// 목표 수를 못 채우는 것은 흔한 실패다 — 격자가 좁거나 그 스테이지의 소켓이
612		// 서로 안 맞으면 프론티어가 먼저 마른다. 조용히 작은 맵이 나오느니 알린다.
613		// 위층 몫은 덧붙는 것이라 목표는 ModuleCount가 아니라 층을 합친 값이다. 위층은 받쳐 주는
614		// 자리에만 서서 목표를 다 못 채우는 게 보통이므로, 1층 몫에도 못 미칠 때만 경고한다.
615		if (Layout.Modules.Num() < Params.ModuleCount)
616		{
617			UE_LOG(LogCL9, Warning, TEXT("Site map: asked for %d modules (%d with upper floors) but only %d fit — check the stage's socket mix (docs/plan/data/module.md)."),
618				Params.ModuleCount, Layout.Wanted, Layout.Modules.Num());
619		}
620		int32 Stairs = 0;
621		for (const FCL9ModulePlacement& Module : Layout.Modules)
622		{
623			Stairs += Module.bStairUp ? 1 : 0;
624		}
625		if (Params.MaxFloors > 1 && Layout.FloorCount < Params.MaxFloors)
626		{
627			UE_LOG(LogCL9, Warning, TEXT("Site map: asked for %d floors but only %d stood — the floor below was too small to carry another (docs/plan/data/module.md)."),
628				Params.MaxFloors, Layout.FloorCount);
629		}
630		UE_LOG(LogCL9, Log, TEXT("Site map built — site '%s', stage '%s', day %d, seed %u, hash %08X, %d of %d modules on a %dx%d grid, %d floors (%.0fcm each) with %d stairs, ceilings %s, %d points, %d instances in %d components."),
631			*Site.Alias.ToString(), *Site.Theme.ToString(), Day, Seed, CL9SiteLayout::LayoutHash(Layout),
632			Layout.Modules.Num(), Layout.Wanted, Layout.GridSize.X, Layout.GridSize.Y, Layout.FloorCount, Params.FloorHeight, Stairs,
633			Params.bBuildCeilings ? TEXT("on") : TEXT("off"),
634			Layout.Points.Num(), Placed, KindComponents.Num());
635		UE_LOG(LogCL9, Log, TEXT("Site map props — %d instances."), PropsPlaced);
636	}
