638	int32 ACL9SiteMap::PlaceProps(const TArray<FCL9SiteSeg>& Segs, int32 FirstComponentIndex)
639	{
640		// 문·비상구 자리 — 몸이 있는 소품이 여길 가리면 문이 막힌다. 층이 다르면 같은 자리라도 무관하다
641		TArray<TPair<FBox2D, float>> Gaps;
642		for (const FCL9SiteSeg& Seg : Segs)
643		{
644			if (Seg.Kind == CL9SegKind::Door() || Seg.Kind == CL9SegKind::FlapIn())
645			{
646				Gaps.Emplace(Seg.Rect, Seg.BaseZ);
647			}
648		}
649	
650		// 스폰이 지점 둘레로 흔드는 폭 — GameMode의 ±(CellSize/2 − 120)과 같다. 항아리는 지점 정중앙에 선다.
651		const float Jitter = FMath::Max(Params.CellSize * 0.5f - 120.f, 0.f);
652		// 시설 조명 밀도 — 같은 시드면 같은 등이 꺼진다 (레이아웃 시드에서 파생, 배치 순서가 시드로 정해진다)
653		FRandomStream LampRng(static_cast<int32>(Layout.Seed ^ 0x5A17u));
654		const float Storey = FMath::Max(Params.FloorHeight, 1.f);
655	
656		// 컴포넌트는 (메시, 몸 유무)마다 하나 — 충돌 설정이 다르면 한 묶음에 넣을 수 없다
657		TMap<TPair<UStaticMesh*, bool>, UInstancedStaticMeshComponent*> Components;
658		auto ComponentFor = [this, &Components, FirstComponentIndex](UStaticMesh* Mesh, bool bSolid)
659		{
660			const TPair<UStaticMesh*, bool> Key(Mesh, bSolid);
661			if (UInstancedStaticMeshComponent* Found = Components.FindRef(Key))
662			{
663				return Found;
664			}
665			UInstancedStaticMeshComponent* Component = NewObject<UInstancedStaticMeshComponent>(
666				this, FName(*FString::Printf(TEXT("Prop_%s_%d"), bSolid ? TEXT("solid") : TEXT("deco"), FirstComponentIndex + Components.Num())));
667			Component->SetMobility(EComponentMobility::Static);
668			Component->SetStaticMesh(Mesh);
669			if (bSolid)
670			{
671				Component->SetCollisionProfileName(UCollisionProfile::BlockAll_ProfileName);
672				Component->SetCanEverAffectNavigation(true);
673			}
674			else
675			{
676				Component->SetCollisionProfileName(UCollisionProfile::NoCollision_ProfileName);
677				Component->SetCanEverAffectNavigation(false);
678			}
679			Component->SetupAttachment(GetRootComponent());
680			Components.Add(Key, Component);
681			KindComponents.Add(Component);
682			return Component;
683		};
684	
685		int32 Placed = 0;
686		TSet<FString> MissingMeshes;
687		for (int32 ModuleIndex = 0; ModuleIndex < Layout.Modules.Num(); ++ModuleIndex)
688		{
689			const FCL9ModulePlacement& Module = Layout.Modules[ModuleIndex];
690			const UCL9ModuleDef* Def = Module.Def;
691			if (Def == nullptr || Def->PropSets.Num() == 0)
692			{
693				continue;
694			}
695	
696			const FBox2D Rect(
697				Layout.Origin + FVector2D(Module.Origin.X * Params.CellSize, Module.Origin.Y * Params.CellSize),
698				Layout.Origin + FVector2D((Module.Origin.X + Module.Size.X) * Params.CellSize, (Module.Origin.Y + Module.Size.Y) * Params.CellSize));
699			const float FloorZ = Module.Floor * Storey;
700	
701			// 세트는 자리 좌표 해시로 뽑는다 — 변형 고르기와 같은 이유로 난수 스트림을 쓰지 않는다
702			const FVector2D Center = Rect.GetCenter();
703			const int32 SetIndex = PickVariant(FVector(Center.X, Center.Y, FloorZ), Def->PropSets.Num());
704			const FCL9PropSet& Set = Def->PropSets[SetIndex];
705	
706			for (const FCL9PropPlacement& Prop : Set.Props)
707			{
708				UStaticMesh* Mesh = Prop.Mesh.LoadSynchronous();
709				if (Mesh == nullptr)
710				{
711					MissingMeshes.Add(FString::Printf(TEXT("%s/%s"), *Def->Alias.ToString(), *Prop.Mesh.ToString()));
712					continue;
713				}
714	
715				const FVector2D Site = CL9SiteLayout::ModuleLocalToSite(Params, Layout, Module, FVector2D(Prop.Local.X, Prop.Local.Y));
716				FTransform Instance;
717				Instance.SetRotation(FRotator(0.f, Prop.Yaw + Module.Rotation * 90.f, 0.f).Quaternion());
718				Instance.SetLocation(FVector(Site.X, Site.Y, FloorZ + Prop.Local.Z));
719				const FBox Footprint = Mesh->GetBoundingBox().TransformBy(Instance);
720				const FBox2D Foot2D(FVector2D(Footprint.Min.X, Footprint.Min.Y), FVector2D(Footprint.Max.X, Footprint.Max.Y));
721	
722				// 변 규칙 — 소품 발자국이 걸친 그 변의 경계 칸을 전부 본다 (300짜리 둥지는 두 칸에 걸친다)
723				if (Prop.SideRule != ECL9PropSideRule::Always && Prop.Side != ECL9PropSide::None)
724				{
725					const int32 Side = CL9SiteLayout::RotateSide(static_cast<int32>(Prop.Side) - 1, Module.Rotation);
726					const bool bAlongX = Side == 0 || Side == 2;
727					const int32 Fixed = Side == 0 ? Module.Origin.Y + Module.Size.Y - 1
728						: Side == 2 ? Module.Origin.Y
729						: Side == 1 ? Module.Origin.X + Module.Size.X - 1
730						: Module.Origin.X;
731					const int32 Count = bAlongX ? Module.Size.X : Module.Size.Y;
732					const int32 First = bAlongX ? Module.Origin.X : Module.Origin.Y;
733					const float Lo = bAlongX ? Foot2D.Min.X : Foot2D.Min.Y;
734					const float Hi = bAlongX ? Foot2D.Max.X : Foot2D.Max.Y;
735					const float Start = bAlongX ? Layout.Origin.X : Layout.Origin.Y;
736	
737					int32 Walls = 0;
738					int32 Openings = 0;
739					for (int32 Index = 0; Index < Count; ++Index)
740					{
741						const float CellLo = Start + (First + Index) * Params.CellSize;
742						if (Hi <= CellLo || Lo >= CellLo + Params.CellSize)
743						{
744							continue;
745						}
746						const FIntPoint Cell = bAlongX ? FIntPoint(First + Index, Fixed) : FIntPoint(Fixed, First + Index);
747						const ECL9GridEdge Edge = CL9SiteLayout::EdgeOfCell(Layout, Module.Floor, Cell, Side);
748						(Edge == ECL9GridEdge::Wall ? Walls : Openings) += 1;
749					}
750					const bool bClosed = Openings == 0 && Walls > 0;
751					if ((Prop.SideRule == ECL9PropSideRule::SideClosed) != bClosed)
752					{
753						continue;
754					}
755				}
756	
757				if (Prop.bSolid)
758				{
759					for (const TPair<FBox2D, float>& Gap : Gaps)
760					{
761						if (FMath::IsNearlyEqual(Gap.Value, FloorZ, 1.f) && Gap.Key.Intersect(Foot2D))
762						{
763							UE_LOG(LogCL9, Warning, TEXT("Site map: prop '%s' in module '%s' set %d (footprint %.0f..%.0f x %.0f..%.0f) covers a doorway at %.0f..%.0f x %.0f..%.0f — move it (docs/plan/data/module.md)."),
764								*Mesh->GetName(), *Def->Alias.ToString(), SetIndex, Foot2D.Min.X, Foot2D.Max.X, Foot2D.Min.Y, Foot2D.Max.Y,
765								Gap.Key.Min.X, Gap.Key.Max.X, Gap.Key.Min.Y, Gap.Key.Max.Y);
766							break;
767						}
768					}
769					for (const FCL9LevelPoint& Point : Layout.Points)
770					{
771						if (Point.Module != ModuleIndex)
772						{
773							continue;
774						}
775						// 경계가 맞닿기만 한 것(벽에 붙인 100cm 둥지가 keep-out 가장자리에 닿는 경우)은 겹침이 아니다
776						const FBox2D KeepOut(Point.Local - FVector2D(Jitter - 1.f, Jitter - 1.f), Point.Local + FVector2D(Jitter - 1.f, Jitter - 1.f));
777						if (KeepOut.Intersect(Foot2D))
778						{
779							UE_LOG(LogCL9, Warning, TEXT("Site map: prop '%s' in module '%s' set %d (footprint %.0f..%.0f x %.0f..%.0f) sits on a spawn point at (%.0f, %.0f) — keep %.0fcm clear of cell centres (docs/plan/data/module.md)."),
780								*Mesh->GetName(), *Def->Alias.ToString(), SetIndex, Foot2D.Min.X, Foot2D.Max.X, Foot2D.Min.Y, Foot2D.Max.Y, Point.Local.X, Point.Local.Y, Jitter);
781							break;
782						}
783					}
784				}
785	
786				ComponentFor(Mesh, Prop.bSolid)->AddInstance(Instance, /*bWorldSpace*/ false);
787				++Placed;
788	
789				if (Prop.LightIntensity > 0.f && LampRng.FRand() < Params.LampDensity)
790				{
791					// 시설 조명 — 인스턴스 메시는 빛을 못 품으므로 소품마다 포인트 라이트를 하나 붙인다.
792					// 밀도(LampDensity)에서 빠진 등은 몸체만 서고 빛이 없다 — 불 꺼진 등.
793					// 그림자를 끄고 반경을 방 하나쯤으로 잡아 수십 개가 서도 무겁지 않게 한다.
794					UPointLightComponent* Lamp = NewObject<UPointLightComponent>(this, FName(*FString::Printf(TEXT("Lamp_%d"), LampComponents.Num())));
795					Lamp->SetMobility(EComponentMobility::Movable);
796					Lamp->SetIntensityUnits(ELightUnits::Candelas);
797					Lamp->SetIntensity(Prop.LightIntensity);
798					Lamp->SetAttenuationRadius(FMath::Max(Prop.LightRadius, 50.f));
799					Lamp->SetLightColor(Prop.LightColor);
800					Lamp->SetCastShadows(false);
801					Lamp->SetVolumetricScatteringIntensity(Prop.LightScattering);
802					Lamp->SetupAttachment(GetRootComponent());
803					Lamp->SetRelativeTransform(FTransform(Instance.GetRotation(), Instance.GetLocation() + Instance.GetRotation().RotateVector(Prop.LightOffset)));
804					Lamp->SetVisibility(bLampsOn);
805					if (Prop.LightFlicker > 0.f && Prop.LightFlickerSpeed > 0.f)
806					{
807						// 위상은 램프 순번에서 — 배치 순서가 시드로 정해지니 같은 시드면 같은 깜박임이고, 램프끼리는 어긋난다
808						// (자리 좌표로 만들면 500cm 격자에 맞은 자리끼리 같은 위상이 나온다 — 09-17 실측)
809						FFlickerLamp Entry;
810						Entry.LampIndex = LampComponents.Num();
811						Entry.BaseIntensity = Prop.LightIntensity;
812						Entry.Amplitude = Prop.LightFlicker;
813						Entry.Speed = Prop.LightFlickerSpeed;
814						Entry.Phase = LampComponents.Num() * 37.f;
815						FlickerLamps.Add(Entry);
816					}
817					LampComponents.Add(Lamp);
818				}
819			}
820		}
821	
822		for (const FString& Missing : MissingMeshes)
823		{
824			UE_LOG(LogCL9, Error, TEXT("Site map: prop mesh '%s' failed to load — skipped (ModuleTable PropSets)."), *Missing);
825		}
826		return Placed;
827	}
